script:
// FPS Overview strip -- design 1a, step 6.
//
// One frappe.call to one whitelisted read-only method. The method omits any tile
// whose doctype the caller cannot read, so this renders what the viewer is
// entitled to see and never reveals the existence of the rest.

(function () {
	var scope =
		typeof root_element !== "undefined" && root_element ? root_element : document;

	var grid = scope.querySelector('[data-fps="grid"]');
	var foot = scope.querySelector('[data-fps="foot"]');
	var meta = scope.querySelector('[data-fps="meta"]');
	if (!grid) return;

	// Tile identity colours, in workflow order. The handoff's oklch() values are
	// the intent, used verbatim here because inside a Custom HTML Block we own the
	// CSS -- unlike shortcuts and cards, which are limited to Frappe's palette.
	var COLOURS = {
		enquiry: "oklch(0.68 0.1 220)",
		quotation: "oklch(0.66 0.11 205)",
		job_order: "oklch(0.62 0.12 195)",
		job_tracker: "oklch(0.66 0.1 265)",
		customs: "oklch(0.65 0.14 75)",
		in_progress: "oklch(0.64 0.13 55)",
		delivered: "oklch(0.62 0.12 150)",
		invoices: "oklch(0.55 0.12 300)",
	};

	function esc(v) {
		return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
			return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
		});
	}

	function render(data) {
		var tiles = (data && data.tiles) || [];
		if (!tiles.length) {
			grid.innerHTML = '<div class="fps-ov-msg">No stages are visible to you.</div>';
			return;
		}

		grid.innerHTML = tiles
			.map(function (t) {
				var colour = COLOURS[t.key] || "#94a3b8";
				var tag = t.route ? "a" : "div";
				var href = t.route ? ' href="' + esc(t.route) + '"' : "";
				return (
					"<" + tag + ' class="fps-ov-cell"' + href +
					' style="--fps-tile-color: ' + colour + '">' +
					'<span class="fps-ov-label">' + esc(t.label) + "</span>" +
					'<span class="fps-ov-count">' + esc(t.count) + "</span>" +
					'<span class="fps-ov-note">' + esc(t.note || "") + "</span>" +
					"</" + tag + ">"
				);
			})
			.join("");

		if (meta) meta.textContent = tiles.length + " stages";

		if (foot) {
			foot.innerHTML = ((data && data.footnotes) || [])
				.map(function (n) {
					return "<span>" + esc(n) + "</span>";
				})
				.join("");
		}
	}

	frappe
		.call({ method: "fps_erpnext.api.pipeline.get_overview" })
		.then(function (r) {
			render(r && r.message);
		})
		.catch(function () {
			grid.innerHTML = '<div class="fps-ov-msg">Could not load the overview.</div>';
		});
})();

style:
/* FPS Overview strip -- eight tiles that WRAP.
   The earlier version used grid-auto-flow: column, which forced one row and made
   the last tile scroll off the right. auto-fit + minmax reflows to 4x2 at desk
   width and 2x4 on a tablet, so nothing is ever hidden off-screen. */

.fps-ov {
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 10px;
	background: var(--card-bg, #fff);
	overflow: hidden;
}

.fps-ov-head {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 14px 16px 12px;
	flex-wrap: wrap;
}

.fps-ov-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color, #1f272e);
}

.fps-ov-help {
	font-size: 12px;
	color: var(--text-muted, #7c7c7c);
}

.fps-ov-meta {
	margin-left: auto;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	font-variant-numeric: tabular-nums;
}

.fps-ov-grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
	border-top: 1px solid var(--border-color, #e2e8f0);
}

.fps-ov-cell {
	position: relative;
	padding: 12px 14px 13px;
	border-left: 1px solid var(--border-color, #e2e8f0);
	border-top: 1px solid var(--border-color, #e2e8f0);
	margin-top: -1px;
	text-decoration: none;
	display: block;
	color: inherit;
	min-width: 0;
}

.fps-ov-cell:hover {
	background: var(--bg-light-gray, #f7f9fa);
	text-decoration: none;
}

/* 3px coloured top edge is the tile's identity. Sits above the wrap border. */
.fps-ov-cell::before {
	content: "";
	position: absolute;
	inset: 0 0 auto 0;
	height: 3px;
	background: var(--fps-tile-color, #94a3b8);
	z-index: 1;
}

.fps-ov-label {
	display: block;
	font-size: 11.5px;
	font-weight: 500;
	color: var(--text-muted, #7c7c7c);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.fps-ov-count {
	display: block;
	margin-top: 4px;
	font-size: 24px;
	font-weight: 600;
	line-height: 1.1;
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-variant-numeric: tabular-nums;
	color: var(--text-color, #1f272e);
}

.fps-ov-note {
	display: block;
	margin-top: 2px;
	font-size: 11px;
	color: var(--text-muted, #7c7c7c);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.fps-ov-foot {
	display: flex;
	flex-wrap: wrap;
	gap: 4px 14px;
	padding: 10px 16px 12px;
	border-top: 1px solid var(--border-color, #e2e8f0);
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
}

.fps-ov-foot span {
	font-variant-numeric: tabular-nums;
}

.fps-ov-msg {
	padding: 18px 16px;
	font-size: 12.5px;
	color: var(--text-muted, #7c7c7c);
}

script:
// Job Tracker board -- one row per open job, colour-coded by customer.
//
// Colour is assigned from the SORTED customer list the server returns, so a
// given customer keeps the same colour across reloads. Deriving it from row
// order instead would reshuffle every time a job was touched.

(function () {
	var scope =
		typeof root_element !== "undefined" && root_element ? root_element : document;

	var body = scope.querySelector('[data-fps="rows"]');
	var legend = scope.querySelector('[data-fps="legend"]');
	var meta = scope.querySelector('[data-fps="meta"]');
	if (!body) return;

	// Customer palette. Deliberately distinct from the five status hues, which
	// carry fixed meanings -- customer identity and job status must not be
	// confusable for one another.
	var PALETTE = [
		"#0B4FE0", "#22D3EE", "#8F4CFF", "#0EA5E9", "#14B8A6",
		"#F59E0B", "#EC4899", "#64748B", "#7C3AED", "#0891B2",
		"#A16207", "#BE185D",
	];

	var STAGE = {
		New: ["#eff6ff", "#1d4ed8"],
		Docs: ["#fff7ed", "#b45309"],
		"In Progress": ["#fef3c7", "#92400e"],
		"Cleared - Ready": ["#ede9fe", "#6d28d9"],
		Delivered: ["#dcfce7", "#15803d"],
		Invoiced: ["#f3e8ff", "#7e22ce"],
		"On Hold": ["#fee2e2", "#b91c1c"],
		Closed: ["#f1f5f9", "#475569"],
	};

	function esc(v) {
		return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
			return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
		});
	}

	function render(data) {
		var jobs = (data && data.jobs) || [];
		var customers = (data && data.customers) || [];

		if (!jobs.length) {
			body.innerHTML =
				'<tr><td colspan="8" class="fps-jt-msg">No open jobs.</td></tr>';
			return;
		}

		var colourOf = {};
		customers.forEach(function (c, i) {
			colourOf[c] = PALETTE[i % PALETTE.length];
		});

		if (legend) {
			legend.innerHTML = customers
				.map(function (c) {
					return (
						'<span class="fps-jt-chip" style="--fps-cust-color: ' +
						colourOf[c] + '"><i></i><span>' + esc(c) + "</span></span>"
					);
				})
				.join("");
		}

		body.innerHTML = jobs
			.map(function (j) {
				var pill = STAGE[j.stage] || ["#f1f5f9", "#475569"];
				return (
					'<tr data-job="' + esc(j.name) + '" title="' + esc(j.name) + '">' +
					'<td class="fps-jt-status"><span class="fps-jt-pill" style="--fps-stage-bg: ' +
					pill[0] + "; --fps-stage-fg: " + pill[1] + '">' +
					esc(j.stage || "—") + "</span></td>" +
					'<td class="fps-jt-cust" style="--fps-cust-color: ' +
					(colourOf[j.customer] || "transparent") + '">' +
					esc(j.customer || "—") + "</td>" +
					'<td class="fps-jt-jo">' + esc(j.name) + "</td>" +
					'<td class="fps-jt-ref">' + esc(j.reference || "—") + "</td>" +
					'<td class="fps-jt-sow" title="' + esc(j.sow) + '">' +
					esc(j.sow || "—") + "</td>" +
					'<td class="fps-jt-cons" title="' + esc(j.consignment) + '">' +
					esc(j.consignment || "—") + "</td>" +
					'<td class="fps-jt-route" title="' + esc(j.route) + '">' +
					esc(j.route || "—") + "</td>" +
					'<td class="fps-jt-eta">' + esc(j.eta || "—") + "</td>" +
					"</tr>"
				);
			})
			.join("");

		if (meta) {
			meta.textContent =
				jobs.length + " open jobs · " + customers.length + " customers";
		}
	}

	// Row click opens the Job Order. Delegated so it survives every re-render,
	// and routed through frappe.set_route rather than an <a href> so the desk
	// navigates in place instead of doing a full page reload.
	body.addEventListener("click", function (e) {
		var row = e.target.closest("tr[data-job]");
		if (!row) return;
		frappe.set_route("Form", "Job Order", row.getAttribute("data-job"));
	});

	frappe
		.call({ method: "fps_erpnext.api.pipeline.get_job_tracker" })
		.then(function (r) {
			render(r && r.message);
		})
		.catch(function () {
			body.innerHTML =
				'<tr><td colspan="8" class="fps-jt-msg">Could not load the job tracker.</td></tr>';
		});
})();

style:
/* Job Tracker board -- one row per open job, colour-coded by customer.
   The five status colours keep their fixed meanings from the handoff and are
   NOT reused for customers; customer identity is carried by the left rail and
   the legend chip, status by the pill. Two separate encodings, so neither can
   be mistaken for the other. */

.fps-jt {
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 10px;
	background: var(--card-bg, #fff);
	overflow: hidden;
}

.fps-jt-head {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 14px 16px 12px;
	flex-wrap: wrap;
}

.fps-jt-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color, #1f272e);
}

.fps-jt-help {
	font-size: 12px;
	color: var(--text-muted, #7c7c7c);
}

.fps-jt-meta {
	margin-left: auto;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	font-variant-numeric: tabular-nums;
}

.fps-jt-legend {
	display: flex;
	flex-wrap: wrap;
	gap: 6px 14px;
	padding: 0 16px 12px;
}

.fps-jt-chip {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	max-width: 240px;
}

.fps-jt-chip i {
	width: 9px;
	height: 9px;
	border-radius: 3px;
	background: var(--fps-cust-color, #94a3b8);
	flex: none;
}

.fps-jt-chip span {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.fps-jt-scroll {
	overflow-x: auto;
	border-top: 1px solid var(--border-color, #e2e8f0);
}

/* table-layout: fixed makes the <colgroup> widths authoritative. Without it the
   browser sizes columns from content, which is what left a gulf between
   "Customer ref" and "Scope of work" -- one long SOW string was pushing the
   remaining columns off to the right. */
.fps-jt-table {
	width: 100%;
	/* Below this the percentage columns would crush the three fixed-length ones
	   back into ellipsis. The container scrolls instead. */
	min-width: 1120px;
	table-layout: fixed;
	border-collapse: collapse;
	font-size: 12.5px;
}

.fps-jt-table th {
	text-align: left;
	font-size: 10.5px;
	font-weight: 600;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-muted, #7c7c7c);
	padding: 9px 10px;
	border-bottom: 1px solid var(--border-color, #e2e8f0);
	white-space: nowrap;
}

.fps-jt-table td {
	padding: 8px 10px;
	border-bottom: 1px solid var(--border-color, #f1f5f9);
	vertical-align: middle;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.fps-jt-table tr:last-child td {
	border-bottom: 0;
}

/* Whole row is the click target, so it must look like one. */
.fps-jt-table tbody tr {
	cursor: pointer;
}

.fps-jt-table tbody tr:hover {
	background: var(--bg-light-gray, #f7f9fa);
}

.fps-jt-status {
	white-space: nowrap;
}

/* Customer identity: coloured left rail plus the name. */
td.fps-jt-cust {
	border-left: 3px solid var(--fps-cust-color, transparent);
	font-weight: 500;
	color: var(--text-color, #1f272e);
}

.fps-jt-jo {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	color: var(--text-color, #1f272e);
}

.fps-jt-ref,
.fps-jt-eta {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
}

.fps-jt-sow,
.fps-jt-cons,
.fps-jt-route {
	color: var(--text-muted, #55606b);
}

.fps-jt-pill {
	display: inline-block;
	padding: 2px 8px;
	border-radius: 20px;
	font-size: 11px;
	font-weight: 600;
	white-space: nowrap;
	background: var(--fps-stage-bg, #f1f5f9);
	color: var(--fps-stage-fg, #475569);
}

.fps-jt-msg {
	padding: 18px 16px;
	font-size: 12.5px;
	color: var(--text-muted, #7c7c7c);
	text-align: left;
	white-space: normal;
}
